import{_ as s,o as n,c as l,a0 as e}from"./chunks/framework.DqMqoJl9.js";const b=JSON.parse('{"title":"String.prototype.localeCompare()","description":"","frontmatter":{},"headers":[],"relativePath":"jsApi/String/localeCompare.md","filePath":"jsApi/String/localeCompare.md","lastUpdated":1791573371000}'),o={name:"jsApi/String/localeCompare.md"};function p(t,a,r,c,i,d){return n(),l("div",null,[...a[0]||(a[0]=[e(`<p><a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/String/localeCompare" target="_blank">原文链接</a><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String/localeCompare" target="_blank">en</a></p><h1 id="string-prototype-localecompare" tabindex="-1">String.prototype.localeCompare() <a class="header-anchor" href="#string-prototype-localecompare" aria-label="Permalink to &quot;String.prototype.localeCompare()&quot;">​</a></h1><p>localeCompare() 方法返回一个数字来指示一个参考字符串是否在排序顺序前面或之后或与给定字符串相同。</p><p>新的 locales 、 options 参数能让应用程序定制函数的行为即指定用来排序的语言。 locales 和 options 参数是依赖于具体实现的， 在旧的实现中这两个参数是完全被忽略的。</p><h2 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to &quot;语法&quot;">​</a></h2><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">referenceStr.</span><span style="color:#6F42C1;">localeCompare</span><span style="color:#24292E;">(compareString[, locales[, options]])</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h3><p>查阅浏览器支持部分来确定哪些浏览器支持 locales 参数和 options 参数， 在功能检测中检查对 locales 、options 参数的支持。</p><ul><li><code>compareString</code> 用来比较的字符串</li></ul><h2 id="描述" tabindex="-1">描述 <a class="header-anchor" href="#描述" aria-label="Permalink to &quot;描述&quot;">​</a></h2><p>返回一个数字表示是否 引用字符串 在排序中位于 比较字符串 的前面，后面，或者二者相同。</p><ul><li>当 引用字符串 在 比较字符串 前面时返回 -1</li><li>当 引用字符串 在 比较字符串 后面时返回 1</li><li>相同位置时返回 0</li></ul><p>切勿依赖于 -1 或 1 这样特定的返回值。不同浏览器之间（以及不同浏览器版本之间） 返回的正负数的值各有不同，因为W3C规范中只 要求返回值是正值和负值，而没有规定具体的值。一些浏览器可能返回-2或2或其他一些负的、正的值。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="使用-localecompare" tabindex="-1">使用 localeCompare() <a class="header-anchor" href="#使用-localecompare" aria-label="Permalink to &quot;使用 localeCompare()&quot;">​</a></h3><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">// The letter &quot;a&quot; is before &quot;c&quot; yielding a negative value</span></span>
<span class="line"><span style="color:#032F62;">&#39;a&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">localeCompare</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;c&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#6A737D;">// -2 or -1 (or some other negative value)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// Alphabetically the word &quot;check&quot; comes after &quot;against&quot; yielding a positive value</span></span>
<span class="line"><span style="color:#032F62;">&#39;check&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">localeCompare</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;against&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#6A737D;">// 2 or 1 (or some other positive value)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// &quot;a&quot; and &quot;a&quot; are equivalent yielding a neutral value of zero</span></span>
<span class="line"><span style="color:#032F62;">&#39;a&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">localeCompare</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;a&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#6A737D;">// 0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h3 id="检查浏览器对扩展参数的支持" tabindex="-1">检查浏览器对扩展参数的支持 <a class="header-anchor" href="#检查浏览器对扩展参数的支持" aria-label="Permalink to &quot;检查浏览器对扩展参数的支持&quot;">​</a></h3><p>locales 和 options 参数还没有被所有阅览器所支持。检查是否被支持， 使用 &quot;i&quot; 参数 (a requirement that illegal language tags are rejected) 判断是否有异常 RangeError抛出:</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">function</span><span style="color:#6F42C1;"> localeCompareSupportsLocales</span><span style="color:#24292E;">() {</span></span>
<span class="line"><span style="color:#D73A49;">  try</span><span style="color:#24292E;"> {</span></span>
<span class="line"><span style="color:#032F62;">    &#39;foo&#39;</span><span style="color:#24292E;">.localeCompare​(</span><span style="color:#032F62;">&#39;bar&#39;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;i&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#24292E;">  } </span><span style="color:#D73A49;">catch</span><span style="color:#24292E;"> (e) {</span></span>
<span class="line"><span style="color:#D73A49;">    return</span><span style="color:#24292E;"> e​.name </span><span style="color:#D73A49;">===</span><span style="color:#032F62;"> &#39;RangeError&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">  }</span></span>
<span class="line"><span style="color:#D73A49;">  return</span><span style="color:#005CC5;"> false</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="使用-locales-参数" tabindex="-1">使用 locales 参数 <a class="header-anchor" href="#使用-locales-参数" aria-label="Permalink to &quot;使用 locales 参数&quot;">​</a></h3><p>在不同的语言下 localeCompare() 所提供的结果是不一致的。 为了能让用户得到正确的比较值， 通过使用 locales 参数来提供要比较 的语言 (and possibly some fallback languages) :</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;ä&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">localeCompare</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;z&#39;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;de&#39;</span><span style="color:#24292E;">)); </span><span style="color:#6A737D;">// a negative value: in German, ä sorts with a</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;ä&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">localeCompare</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;z&#39;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;sv&#39;</span><span style="color:#24292E;">)); </span><span style="color:#6A737D;">// a positive value: in Swedish, ä sorts after z</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="使用-options-参数" tabindex="-1">使用 options 参数 <a class="header-anchor" href="#使用-options-参数" aria-label="Permalink to &quot;使用 options 参数&quot;">​</a></h3><p>localeCompare() 所提供的结果可以通过 options 参数来制定:</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">// in German, ä has a as the base letter</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;ä&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">localeCompare</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;a&#39;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;de&#39;</span><span style="color:#24292E;">, { sensitivity: </span><span style="color:#032F62;">&#39;base&#39;</span><span style="color:#24292E;"> })); </span><span style="color:#6A737D;">// 0</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// in Swedish, ä and a are separate base letters</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;ä&#39;</span><span style="color:#24292E;">.</span><span style="color:#6F42C1;">localeCompare</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;a&#39;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;sv&#39;</span><span style="color:#24292E;">, { sensitivity: </span><span style="color:#032F62;">&#39;base&#39;</span><span style="color:#24292E;"> })); </span><span style="color:#6A737D;">// a positive value</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="性能相关" tabindex="-1">性能相关 <a class="header-anchor" href="#性能相关" aria-label="Permalink to &quot;性能相关&quot;">​</a></h2><p>当比较大量字符串时， 比如比较大量数组时， 最好创建一个Intl.Collator 对象并使用compare 属性所提供的函数。</p><h2 id="规范" tabindex="-1">规范 <a class="header-anchor" href="#规范" aria-label="Permalink to &quot;规范&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Specification</th><th style="text-align:left;">Status</th><th style="text-align:left;">Comment</th></tr></thead><tbody><tr><td style="text-align:left;">ECMAScript 3rd Edition (ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;">Initial definition</td></tr><tr><td style="text-align:left;">ECMAScript 5.1 (ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">ECMAScript 2015 (6th Edition, ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;"></td></tr></tbody></table>`,29)])])}const u=s(o,[["render",p]]);export{b as __pageData,u as default};
